M(cfg, r"""
public static int skillSlot(String lower) {
  for (int i = 0; i < SK_NAMES.length; i++) if (SK_NAMES[i].equals(lower)) return SK_SLOTS[i];
  return -1;
}""")
# 0.1.3 (review fix): each skill counts ONCE - the first name of a known slot wins (Fury,Berserker -> Fury), a name listed again in any
# case is dropped (an unknown name too); one WARN per parse names what was dropped. The file keeps its text (the kit owns every write).
M(cfg, r"""
public static void parseSkills(java.util.Properties p) {
  String sk = p.getProperty("xpSkills");
  if (sk == null || sk.trim().length() == 0) sk = DEF_SKILLS;
  String[] a = sk.split(",");
  java.util.ArrayList l = new java.util.ArrayList();
  java.util.HashSet names = new java.util.HashSet();
  java.util.HashMap slots = new java.util.HashMap();
  StringBuilder dup = new StringBuilder();
  for (int i = 0; i < a.length; i++) {
    String x = a[i].trim();
    if (x.length() == 0 || x.equalsIgnoreCase("combat")) continue;
    String lx = x.toLowerCase();
    int s = skillSlot(lx);
    Object first = s >= 0 ? slots.get(Integer.valueOf(s)) : null;
    if (first != null || names.contains(lx)) {
      if (dup.length() > 0) dup.append(", ");
      if (first != null && !((String) first).equalsIgnoreCase(x)) dup.append(x).append(" = ").append((String) first);
      else dup.append(x).append(" twice");
      continue;
    }
    names.add(lx);
    if (s >= 0) slots.put(Integer.valueOf(s), x);
    l.add(x);
  }
  String[] r = new String[l.size()];
  for (int i = 0; i < r.length; i++) r[i] = (String) l.get(i);
  SKILLS = r;
  if (dup.length() > 0) {
    String d = dup.length() > 300 ? dup.substring(0, 300) + "..." : dup.toString();
    @PKG@.GuildStore.warn("config.properties: xpSkills names the same skill more than once (" + d + ") - it counts once. Save the list once per skill in Server Setup > Guilds > Skills that count (or /guildadmin set xpSkills <list>) to remove this warning.");
  }
}""")
M(cfg, r"""
public static void parseLimits(java.util.Properties p) {
  DEF_LIM_ADMIN = limProp(p, "defaultAdminLimit", -1L);
  DEF_LIM_MEMBER = limProp(p, "defaultMemberLimit", 0L);
}""")
