# ---- 0.1.3: the xpSkills migration (setup only, inside load(), BEFORE the config kit starts - the kit owns every write after that).
# Only an xpSkills value that is still exactly OLD_SKILLS gets DEF_SKILLS; only that value text changes (see the 0.1.3 header block).
M(cfg, r"""
public static boolean isWs(char c) {
  return c == ' ' || c == '\t' || c == 12;
}""")
# where the value of a live xpSkills line starts (Properties syntax: white space, the key, then white space and / or one = or :);
# -1 = not an xpSkills line. body = the line without its CR.
M(cfg, r"""
public static int skillsValueAt(String body) {
  int n = body.length();
  int i = 0;
  while (i < n && isWs(body.charAt(i))) i++;
  if (!body.startsWith("xpSkills", i)) return -1;
  i = i + 8;
  int j = i;
  while (j < n && isWs(body.charAt(j))) j++;
  if (j < n && (body.charAt(j) == '=' || body.charAt(j) == ':')) {
    j++;
    while (j < n && isWs(body.charAt(j))) j++;
  } else if (j == i && j < n) return -1;
  return j;
}""")
# a logical line that continues on the next one (an odd number of trailing backslashes)
M(cfg, r"""
public static boolean contLine(String body) {
  int k = 0;
  int i = body.length() - 1;
  while (i >= 0 && body.charAt(i) == '\\') { k++; i--; }
  return k % 2 == 1;
}""")
M(cfg, r"""
public static boolean commentOrBlank(String body) {
  int n = body.length();
  int i = 0;
  while (i < n && isWs(body.charAt(i))) i++;
  return i >= n || body.charAt(i) == '#' || body.charAt(i) == '!';
}""")
# the new default skills (Fury, Divinity) a list names by none of their SkyySkills 0.4.4 names ("" = both listed)
