    b.appendInline("#SkyyGLNav", "Label #SkyyGLPageTxt { Anchor: (Width: 170, Height: 34); Text: \"\"; Style: (FontSize: 15, TextColor: #9fb8d0, HorizontalAlignment: Center, VerticalAlignment: Center); }");
